  font-size: 24px;
  color: var(--text-mute);
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 80px;
}
.brand-item::after {
  content: '✦';
  color: var(--border-strong);
  font-size: 14px;
}

/* ======================== SECTION ======================== */
section { padding: 100px 0; }
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 48px;
  gap: 32px;
}
.section-eyebrow {
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}
.section-title {
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: clamp(32px, 4vw, 52px);
  letter-spacing: -0.03em;
  line-height: 1.05;
  max-width: 700px;
}
.section-title em { font-style: italic; color: var(--text-dim); font-weight: 400; }
.section-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-dim);
  font-size: 14px;
  font-weight: 500;
  border-bottom: 1px solid var(--border-strong);
  padding-bottom: 4px;
  transition: color .15s, border-color .15s;
  white-space: nowrap;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); }

/* ======================== PRODUCT TABS ======================== */
.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 40px;
  border-bottom: 1px solid var(--border);
}
.tab {
  padding: 14px 20px;
  font-size: 14px;
  color: var(--text-mute);
  font-weight: 500;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color .15s, border-color .15s;
}
.tab:hover { color: var(--text-dim); }
.tab.active { color: var(--text); border-color: var(--accent); }
.tab-count {
  font-size: 11px;
  color: var(--text-mute);
  margin-left: 6px;
}

/* ======================== PRODUCT GRID ======================== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  position: relative;
  cursor: pointer;
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--bg-elev);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 16px;
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .6s cubic-bezier(.2,.8,.2,1);
}
.product:hover .product-media img { transform: scale(1.06); }

.product-tags {
  position: absolute;
  top: 12px; left: 12px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.tag-pill {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 100px;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--text);
}
.tag-pill.new { background: var(--accent); color: #000; }
.tag-pill.sale { background: var(--warn); }
.tag-pill.low { background: rgba(0,0,0,0.6); color: var(--gold); }

.wish {
  position: absolute;
  top: 12px; right: 12px;
  width: 36px; height: 36px;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  transition: background .15s, color .15s;
}
.wish:hover { background: var(--accent); color: #000; }
.wish.active { color: var(--warn); }
.wish svg { width: 16px; height: 16px; }

.product-quick {
  position: absolute;
  bottom: 12px; left: 12px; right: 12px;
  background: rgba(10,10,11,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .25s, transform .25s;
}
.product:hover .product-quick { opacity: 1; transform: translateY(0); }
.product-quick svg { width: 14px; height: 14px; }

.product-meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}
.product-info { flex: 1; min-width: 0; }
.product-cat {
  font-size: 11px;
  color: var(--text-mute);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 4px;
}
.product-name {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 6px;
  color: var(--text);
}
.product-swatches {
  display: flex;
  gap: 5px;
  margin-top: 8px;
}
.swatch {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  cursor: pointer;
}
.product-price {
  text-align: right;
  font-size: 14px;
  font-weight: 600;
}
.price-old {
  display: block;
  color: var(--text-mute);
  font-weight: 400;
  font-size: 12px;
  text-decoration: line-through;
}
.price-sale { color: var(--warn); }
.product-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-dim);
  margin-top: 4px;
}
.product-rating svg { width: 11px; height: 11px; color: var(--accent); }

/* ======================== DEALS ======================== */
.deals-section {
  background: linear-gradient(180deg, var(--bg) 0%, #0d0d0f 100%);
}
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  height: 620px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  background: var(--bg-elev);
  transition: transform .3s;
}
.deal-card:hover { transform: translateY(-4px); }
.deal-card.featured {
  grid-row: span 2;
}
.deal-card img {
  width: 100%; height: 100%;
  object-fit: cover;
  filter: brightness(0.85);
  transition: transform .6s cubic-bezier(.2,.8,.2,1);
}
.deal-card:hover img { transform: scale(1.04); }
.deal-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.85) 100%);
  pointer-events: none;
}
.deal-content {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 28px;
  z-index: 2;
}
.deal-card.featured .deal-content { padding: 36px; }
.deal-discount {
  display: inline-block;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.06em;
  padding: 6px 12px;
  border-radius: 100px;
  margin-bottom: 14px;
}
.deal-discount.warm { background: var(--warn); color: #fff; }
.deal-title {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}
.deal-card.featured .deal-title { font-size: 38px; line-height: 1.05; }
.deal-sub {
  color: var(--text-dim);
  font-size: 13px;
  margin-bottom: 16px;
}
.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  border-bottom: 1px solid var(--text);
  padding-bottom: 2px;
}
.deal-timer {
  position: absolute;
  top: 24px; right: 24px;
  display: flex;
  gap: 6px;
  z-index: 2;
}
.timer-block {
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 10px 12px;
  border-radius: 8px;
  text-align: center;
  min-width: 50px;
}
.timer-num {
  font-family: 'Fraunces', serif;
  font-size: 20px;
  font-weight: 600;
  display: block;
  line-height: 1;
}
.timer-label {
  font-size: 9px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-top: 4px;
}

/* ======================== CATEGORY CHIPS ======================== */
.categories {
  padding: 60px 0;
  background: #08080a;
  border-block: 1px solid var(--border);
}
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat-card {
  aspect-ratio: 1;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: border-color .2s, background .2s, transform .2s;
}
.cat-card:hover {
  border-color: var(--accent);
  background: var(--bg-elev-2);
  transform: translateY(-3px);
}
.cat-icon {
  width: 36px; height: 36px;
  background: var(--bg-elev-2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.cat-name {
  font-size: 14px;
  font-weight: 500;
}
.cat-count {
  font-size: 11px;
  color: var(--text-mute);
  margin-top: 2px;
}

/* ======================== EDITORIAL ======================== */
.editorial {
  background: var(--bg);
}
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.article {
  cursor: pointer;
  display: flex;
  flex-direction: column;
}
.article-media {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 20px;
  background: var(--bg-elev);
}
.article.feat .article-media { aspect-ratio: 5/6; }
.article-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s;
}
.article:hover .article-media img { transform: scale(1.05); }
.article-cat {
  position: absolute;
  top: 16px; left: 16px;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 100px;
  font-weight: 600;
}
.article-meta {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-mute);
  margin-bottom: 10px;
  display: flex;
  gap: 12px;
}
.article-title {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 10px;
  transition: color .2s;
}
.article.feat .article-title { font-size: 32px; }
.article:hover .article-title { color: var(--accent); }
.article-excerpt {
  color: var(--text-dim);
  font-size: 14px;
  line-height: 1.55;
  margin-bottom: 14px;
}
.article-author {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
}
.author-ava {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--text-dim);
  font-weight: 600;
}
.author-name {
  font-size: 13px;
  font-weight: 500;
}
.author-role {
  font-size: 11px;
  color: var(--text-mute);
}

/* ======================== FEATURE CARDS ======================== */
.values {
  background: #08080a;
  padding: 80px 0;
  border-top: 1px solid var(--border);
}
.values-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--border);
