}
.btn-primary:hover { background: var(--accent-soft); }
.btn-ghost {
  border: 1px solid var(--border-strong);
  color: var(--text);
}
.btn-ghost:hover { border-color: var(--text); background: var(--bg-elev); }

.hero-stats {
  display: flex;
  gap: 40px;
  border-top: 1px solid var(--border);
  padding-top: 28px;
}
.stat-num {
  font-family: 'Fraunces', serif;
  font-size: 28px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.02em;
}
.stat-label {
  font-size: 12px;
  color: var(--text-mute);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-top: 4px;
}

.hero-visual {
  position: relative;
  aspect-ratio: 5/4;
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(135deg, #1a1a1d 0%, #0a0a0b 100%);
  box-shadow: var(--shadow);
}
.hero-visual img {
  width: 100%; height: 100%;
  object-fit: cover;
  filter: brightness(0.92) contrast(1.05);
}
.hero-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.5) 100%);
  pointer-events: none;
}
.hero-tag {
  position: absolute;
  bottom: 24px;
  left: 24px;
  background: rgba(10,10,11,0.75);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  padding: 16px 20px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  gap: 14px;
  border: 1px solid rgba(255,255,255,0.08);
}
.hero-tag .tag-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%,100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.3); }
}
.tag-text { font-size: 13px; }
.tag-text strong { display: block; }
.tag-text small { color: var(--text-dim); font-size: 11px; }

.hero-badge {
  position: absolute;
  top: 24px; right: 24px;
  width: 110px; height: 110px;
  border-radius: 50%;
  background: var(--accent);
  color: #000;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: 13px;
  text-align: center;
  line-height: 1.1;
  animation: rotate 20s linear infinite;
  padding: 16px;
}
.hero-badge span { display: block; }
.hero-badge .num {
  font-size: 28px;
  display: block;
  margin: 4px 0;
}
@keyframes rotate {
  to { transform: rotate(360deg); }
}

/* ======================== MARQUEE ======================== */
.brand-strip {
  border-block: 1px solid var(--border);
  padding: 28px 0;
  overflow: hidden;
  background: #08080a;
}
.brand-track {
  display: flex;
  gap: 80px;
  animation: scroll 40s linear infinite;
  white-space: nowrap;
}
@keyframes scroll {
  to { transform: translateX(-50%); }
}
.brand-item {
  font-family: 'Fraunces', serif;
  font-size: 24px;
  color: var(--text-mute);
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 80px;
}
.brand-item::after {
  content: '✦';
  color: var(--border-strong);
  font-size: 14px;
}

/* ======================== SECTION ======================== */
section { padding: 100px 0; }
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 48px;
  gap: 32px;
}
.section-eyebrow {
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}
.section-title {
  font-family: 'Fraunces', serif;
  font-weight: 600;
  font-size: clamp(32px, 4vw, 52px);
  letter-spacing: -0.03em;
  line-height: 1.05;
  max-width: 700px;
}
.section-title em { font-style: italic; color: var(--text-dim); font-weight: 400; }
.section-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-dim);
  font-size: 14px;
  font-weight: 500;
  border-bottom: 1px solid var(--border-strong);
  padding-bottom: 4px;
  transition: color .15s, border-color .15s;
  white-space: nowrap;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); }

/* ======================== PRODUCT TABS ======================== */
.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 40px;
  border-bottom: 1px solid var(--border);
}
.tab {
  padding: 14px 20px;
  font-size: 14px;
  color: var(--text-mute);
  font-weight: 500;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color .15s, border-color .15s;
}
.tab:hover { color: var(--text-dim); }
.tab.active { color: var(--text); border-color: var(--accent); }
.tab-count {
  font-size: 11px;
  color: var(--text-mute);
  margin-left: 6px;
}

/* ======================== PRODUCT GRID ======================== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  position: relative;
  cursor: pointer;
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--bg-elev);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 16px;
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .6s cubic-bezier(.2,.8,.2,1);
}
.product:hover .product-media img { transform: scale(1.06); }

.product-tags {
  position: absolute;
  top: 12px; left: 12px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.tag-pill {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 100px;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--text);
}
.tag-pill.new { background: var(--accent); color: #000; }
.tag-pill.sale { background: var(--warn); }
.tag-pill.low { background: rgba(0,0,0,0.6); color: var(--gold); }

.wish {
  position: absolute;
  top: 12px; right: 12px;
  width: 36px; height: 36px;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text);
  transition: background .15s, color .15s;
}
.wish:hover { background: var(--accent); color: #000; }
.wish.active { color: var(--warn); }
.wish svg { width: 16px; height: 16px; }

.product-quick {
  position: absolute;
  bottom: 12px; left: 12px; right: 12px;
  background: rgba(10,10,11,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  display: flex;
  justify-content: space-between;
  align-items: center;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .25s, transform .25s;
}
.product:hover .product-quick { opacity: 1; transform: translateY(0); }
.product-quick svg { width: 14px; height: 14px; }

.product-meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}
.product-info { flex: 1; min-width: 0; }
.product-cat {
  font-size: 11px;
  color: var(--text-mute);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 4px;
}
.product-name {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 6px;
  color: var(--text);
}
.product-swatches {
  display: flex;
  gap: 5px;
  margin-top: 8px;
}
.swatch {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  cursor: pointer;
}
.product-price {
  text-align: right;
  font-size: 14px;
  font-weight: 600;
}
.price-old {
  display: block;
  color: var(--text-mute);
  font-weight: 400;
  font-size: 12px;
  text-decoration: line-through;
}
.price-sale { color: var(--warn); }
.product-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-dim);
  margin-top: 4px;
}
.product-rating svg { width: 11px; height: 11px; color: var(--accent); }

/* ======================== DEALS ======================== */
.deals-section {
  background: linear-gradient(180deg, var(--bg) 0%, #0d0d0f 100%);
}
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
  height: 620px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  background: var(--bg-elev);
  transition: transform .3s;
}
.deal-card:hover { transform: translateY(-4px); }
.deal-card.featured {
  grid-row: span 2;
}
.deal-card img {
  width: 100%; height: 100%;
  object-fit: cover;
  filter: brightness(0.85);
  transition: transform .6s cubic-bezier(.2,.8,.2,1);
}
.deal-card:hover img { transform: scale(1.04); }
.deal-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.85) 100%);
  pointer-events: none;
}
.deal-content {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 28px;
  z-index: 2;
}
.deal-card.featured .deal-content { padding: 36px; }
.deal-discount {
  display: inline-block;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.06em;
  padding: 6px 12px;
  border-radius: 100px;
  margin-bottom: 14px;
}
.deal-discount.warm { background: var(--warn); color: #fff; }
.deal-title {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}
.deal-card.featured .deal-title { font-size: 38px; line-height: 1.05; }
.deal-sub {
  color: var(--text-dim);
  font-size: 13px;
  margin-bottom: 16px;
}
.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  border-bottom: 1px solid var(--text);
  padding-bottom: 2px;
}
.deal-timer {
  position: absolute;
  top: 24px; right: 24px;
  display: flex;
  gap: 6px;
  z-index: 2;
}
.timer-block {
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 10px 12px;
  border-radius: 8px;
  text-align: center;
  min-width: 50px;
}
.timer-num {
  font-family: 'Fraunces', serif;
  font-size: 20px;
  font-weight: 600;
  display: block;
  line-height: 1;
}
.timer-label {
  font-size: 9px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-top: 4px;
}

/* ======================== CATEGORY CHIPS ======================== */
.categories {
  padding: 60px 0;
  background: #08080a;
  border-block: 1px solid var(--border);
}
.cat-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat-card {
  aspect-ratio: 1;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: border-color .2s, background .2s, transform .2s;
}
.cat-card:hover {
  border-color: var(--accent);
  background: var(--bg-elev-2);
  transform: translateY(-3px);
}
.cat-icon {
  width: 36px; height: 36px;
  background: var(--bg-elev-2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}
.cat-name {
  font-size: 14px;
  font-weight: 500;
}
.cat-count {
  font-size: 11px;
  color: var(--text-mute);
  margin-top: 2px;
}

/* ======================== EDITORIAL ======================== */
.editorial {
  background: var(--bg);
}
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.article {
  cursor: pointer;
  display: flex;
  flex-direction: column;
}
.article-media {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 20px;
  background: var(--bg-elev);
}
.article.feat .article-media { aspect-ratio: 5/6; }
.article-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s;
}
.article:hover .article-media img { transform: scale(1.05); }
.article-cat {
  position: absolute;
  top: 16px; left: 16px;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 100px;
  font-weight: 600;
}
.article-meta {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-mute);
  margin-bottom: 10px;
  display: flex;
  gap: 12px;
}
.article-title {
  font-family: 'Fraunces', serif;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 10px;
  transition: color .2s;
}
.article.feat .article-title { font-size: 32px; }
.article:hover .article-title { color: var(--accent); }
.article-excerpt {
  color: var(--text-dim);
  font-size: 14px;
  line-height: 1.55;
  margin-bottom: 14px;
}
.article-author {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
}
.author-ava {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--text-dim);
  font-weight: 600;
}
.author-name {
  font-size: 13px;
  font-weight: 500;
}
.author-role {
  font-size: 11px;
  color: var(--text-mute);
}

/* ======================== FEATURE CARDS ======================== */
.values {
  background: #08080a;
  padding: 80px 0;
  border-top: 1px solid var(--border);
}
.values-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--border);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}
.value {
  background: var(--bg);
  padding: 36px 28px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.value-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: var(--bg-elev-2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
}
.value-icon svg { width: 22px; height: 22px; }
.value-title {
  font-size: 15px;
  font-weight: 600;
}
.value-desc {
  color: var(--text-dim);
  font-size: 13px;
  line-height: 1.55;
}

/* ======================== NEWSLETTER ======================== */
.newsletter {
  padding: 120px 0;
  background:
    radial-gradient(ellipse at top, rgba(212,255,58,0.06) 0%, transparent 50%),
    var(--bg);
  border-top: 1px solid var(--border);
}
.news-inner {
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
}
.news-eye {
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 16px;
}
.news-title {
  font-family: 'Fraunces', serif;
  font-size: clamp(36px, 5vw, 60px);
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.05;
  margin-bottom: 18px;
}
.news-desc {
  color: var(--text-dim);
  margin-bottom: 36px;
  font-size: 16px;
}
.news-form {
  display: flex;
  gap: 8px;
  background: var(--bg-elev);
  border: 1px solid var(--border-strong);
  border-radius: 100px;
  padding: 6px;
  max-width: 480px;
  margin: 0 auto;
  transition: border-color .15s;
}
.news-form:focus-within { border-color: var(--accent); }
.news-form input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  font: inherit;
  padding: 0 18px;
  font-size: 14px;
}
.news-form input::placeholder { color: var(--text-mute); }
.news-form button {
  background: var(--accent);
  color: #000;
  padding: 12px 22px;
  border-radius: 100px;
  font-weight: 600;
  font-size: 13px;
  transition: background .15s;
}
.news-form button:hover { background: var(--accent-soft); }
.news-fine {
  color: var(--text-mute);
  font-size: 12px;
  margin-top: 18px;
}

/* ======================== FOOTER ======================== */
footer {
  background: #050506;
  border-top: 1px solid var(--border);
  padding: 80px 0 32px;
}
.foot-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 60px;
}
.foot-brand {
  font-family: 'Fraunces', serif;
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.04em;
  margin-bottom: 16px;
}
.foot-brand .brand-dot { width: 10px; height: 10px; }
.foot-tag {
  color: var(--text-dim);
  font-size: 14px;
  max-width: 280px;
  margin-bottom: 24px;
  line-height: 1.6;
}
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  border: 1px solid var(--border);
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-dim);
  transition: all .2s;
}
.socials a:hover {
  background: var(--accent);
  color: #000;
  border-color: var(--accent);
}
.socials svg { width: 16px; height: 16px; }
.foot-col h4 {
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-mute);
  margin-bottom: 18px;
  font-weight: 600;
}
.foot-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.foot-col a {
  color: var(--text-dim);
  font-size: 14px;
  transition: color .15s;
}
.foot-col a:hover { color: var(--accent); }

.foot-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 28px;
  border-top: 1px solid var(--border);
  color: var(--text-mute);
  font-size: 12px;
}
.payments { display: flex; gap: 8px; }
.pay {
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-dim);
}

/* ======================== RESPONSIVE ======================== */
@media (max-width: 1100px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(4, 1fr); }
  .deals-grid { height: auto; grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .deal-card.featured { grid-column: span 2; aspect-ratio: 16/9; grid-row: auto; }
  .deal-card:not(.featured) { aspect-ratio: 4/3; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .article.feat { grid-column: span 2; }
  .article.feat .article-media { aspect-ratio: 16/9; }
  .values-grid { grid-template-columns: repeat(2, 1fr); }
  .foot-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}
@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .topbar-marquee span:not(:first-child) { display: none; }
  .nav-primary { display: none; }
  .header-inner { grid-template-columns: 1fr auto 1fr; }
  .hero { padding: 40px 0 60px; }
  .hero-inner { grid-template-columns: 1fr; gap: 40px; }
  .hero-stats { gap: 20px; flex-wrap: wrap; }
  section { padding: 60px 0; }
  .section-head { flex-direction: column; align-items: flex-start; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.featured { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .article.feat { grid-column: auto; }
  .values-grid { grid-template-columns: 1fr; }
  .foot-grid { grid-template-columns: 1fr; }
  .foot-bottom { flex-direction: column; gap: 16px; text-align: center; }
}
